1	package zkcircuit
2	
3	import (
4		"sort"
5		"strings"
6	)
7	
8	// This file holds the domain operations of the persistent workbench. Every
9	// mutating operation validates its request before touching state, runs under
10	// the shared process lock and either commits one complete new state or
11	// commits nothing.
12	
13	// CreateCircuit creates a draft circuit version identified by Name+Version.
14	//
15	// The name must be non-empty and not only whitespace; Version must be
16	// positive; Constraints must be positive; the input counts must not be
17	// negative. Creating an already-existing version is idempotent when the
18	// description is identical (the stored record is returned unchanged); a
19	// differing description is reported as ErrConflict. Nothing about an
20	// existing version — frozen or not — is ever replaced by Create.
21	func (s *Store) CreateCircuit(c Circuit) (Circuit, error) {
22		if err := validateCircuitKey(c.Name, c.Version); err != nil {
23			return Circuit{}, err
24		}
25		if err := validateCounts(c.Constraints, c.PublicInputs, c.PrivateInputs); err != nil {
26			return Circuit{}, err
27		}
28	
29		var result Circuit
30		err := s.withLock(func() (bool, error) {
31			if existing := findCircuit(s.data.Circuits, c.Name, c.Version); existing != nil {
32				if existing.Description != c.Description {
33					return false, conflictf("circuit %q version %d already exists with a different description", c.Name, c.Version)
34				}
35				result = circuitFromPersist(*existing)
36				return false, nil
37			}
38			record := persistCircuit{
39				Name: c.Name, Version: c.Version,
40				Constraints: c.Constraints, PublicInputs: c.PublicInputs, PrivateInputs: c.PrivateInputs,
41				Frozen: false, Description: c.Description,
42			}
43			s.data.Circuits = append(s.data.Circuits, record)
44			result = circuitFromPersist(record)
45			return true, nil
46		})
47		return result, err
48	}
49	
50	// UpdateCircuit modifies a draft circuit version. It must target an existing,
51	// unfrozen version explicitly: unknown versions yield ErrNotFound and frozen
52	// versions yield ErrFrozen. On success the counts and description are
53	// replaced as one atomic change; partial updates can never be observed.
54	func (s *Store) UpdateCircuit(c Circuit) (Circuit, error) {
55		if err := validateCircuitKey(c.Name, c.Version); err != nil {
56			return Circuit{}, err
57		}
58		if err := validateCounts(c.Constraints, c.PublicInputs, c.PrivateInputs); err != nil {
59			return Circuit{}, err
60		}
61	
62		var result Circuit
63		err := s.withLock(func() (bool, error) {
64			existing := findCircuit(s.data.Circuits, c.Name, c.Version)
65			if existing == nil {
66				return false, notFoundf("circuit %q version %d does not exist", c.Name, c.Version)
67			}
68			if existing.Frozen {
69				return false, frozenf("circuit %q version %d is frozen and its description cannot be modified", c.Name, c.Version)
70			}
71			// When a definition is already imported, changing the three counts is
72			// only accepted as a whole if the definition stays legal under them
73			// (exact constraint count, all wires inside the new input layout).
74			if existing.Definition != nil {
75				parsed, perr := definitionFromPersist(*existing.Definition, existing.PublicInputs, existing.PrivateInputs)
76				if perr != nil {
77					return false, corruptf("stored definition for %q v%d is unreadable: %v", c.Name, c.Version, perr)
78				}
79				if !parsed.compatibleWith(c.Constraints, c.PublicInputs, c.PrivateInputs) {
80					return false, invalidf("update rejected: it would make the imported constraint definition illegal (constraint count or wire layout mismatch); the whole change is refused")
81				}
82			}
83			existing.Constraints = c.Constraints
84			existing.PublicInputs = c.PublicInputs
85			existing.PrivateInputs = c.PrivateInputs
86			existing.Description = c.Description
87			result = circuitFromPersist(*existing)
88			return true, nil
89		})
90		return result, err
91	}
92	
93	// FreezeCircuit freezes a circuit version. Unknown versions yield
94	// ErrNotFound. Freezing an already-frozen version returns that version
95	// unchanged (idempotent). Once frozen, name, version and the three counts
96	// can never change again.
97	func (s *Store) FreezeCircuit(name string, version int) (Circuit, error) {
98		if err := validateCircuitKey(name, version); err != nil {
99			return Circuit{}, err
100		}
101	
102		var result Circuit
103		err := s.withLock(func() (bool, error) {
104			existing := findCircuit(s.data.Circuits, name, version)
105			if existing == nil {
106				return false, notFoundf("circuit %q version %d does not exist", name, version)
107			}
108			if existing.Frozen {
109				result = circuitFromPersist(*existing)
110				return false, nil
111			}
112			existing.Frozen = true
113			result = circuitFromPersist(*existing)
114			return true, nil
115		})
116		return result, err
117	}
118	
119	// RecordSetup records a trusted setup for one frozen circuit version. The
120	// record belongs exclusively to that name+version. Unknown versions yield
121	// ErrNotFound; non-frozen versions yield ErrNotFrozen. Re-registering a
122	// setup for the same version is idempotent and adds no duplicate record.
123	func (s *Store) RecordSetup(name string, version int) (Setup, error) {
124		if err := validateCircuitKey(name, version); err != nil {
125			return Setup{}, err
126		}
127	
128		var result Setup
129		err := s.withLock(func() (bool, error) {
130			circuit := findCircuit(s.data.Circuits, name, version)
131			if circuit == nil {
132				return false, notFoundf("circuit %q version %d does not exist", name, version)
133			}
134			if !circuit.Frozen {
135				return false, notFrozenf("circuit %q version %d must be frozen before its trusted setup is recorded", name, version)
136			}
137			if existing := findSetup(s.data.Setups, name, version); existing != nil {
138				result = setupFromPersist(*existing)
139				return false, nil
140			}
141			record := persistSetup{Name: name, Version: version}
142			s.data.Setups = append(s.data.Setups, record)
143			result = setupFromPersist(record)
144			return true, nil
145		})
146		return result, err
147	}
148	
149	// SubmitJob accepts and stores a prove job. Only kind "prove" is accepted;
150	// no proving computation runs, the accepted request alone is persisted.
151	//
152	// The job id must be non-empty and not only whitespace, circuit name and
153	// version must be explicit and Attempt must be positive. Failure reasons are
154	// distinguishable: ErrNotFound (version unknown), ErrNotFrozen (version is
155	// still a draft) and ErrSetupMissing (no trusted setup for that version). A
156	// refused submission leaves no job behind.
157	//
158	// Resubmitting the same id with the same request returns the stored job;
159	// the same id with different content yields ErrConflict. A stored job stays
160	// pinned to the version submitted, regardless of circuit versions added
161	// later.
162	func (s *Store) SubmitJob(job Job) (Job, error) {
163		if strings.TrimSpace(job.ID) == "" {
164			return Job{}, invalidf("job id must be non-empty and not only whitespace")
165		}
166		if strings.TrimSpace(job.Circuit) == "" {
167			return Job{}, invalidf("job %q must name a circuit", job.ID)
168		}
169		if job.Version <= 0 {
170			return Job{}, invalidf("job %q must pin a positive circuit version", job.ID)
171		}
172		if job.Attempt <= 0 {
173			return Job{}, invalidf("job %q attempt must be a positive integer", job.ID)
174		}
175		if job.Kind != "prove" {
176			return Job{}, StoreError{Kind: ErrUnsupportedKind.Kind,
177				Detail: "job " + job.ID + " has unsupported kind " + job.Kind + "; only \"prove\" jobs are accepted"}
178		}
179	
180		var result Job
181		err := s.withLock(func() (bool, error) {
182			if existing := findJob(s.data.Jobs, job.ID); existing != nil {
183				if !sameJobRequest(*existing, job) {
184					return false, conflictf("job %q already exists with a different request", job.ID)
185				}
186				result = jobFromPersist(*existing)
187				return false, nil
188			}
189			circuit := findCircuit(s.data.Circuits, job.Circuit, job.Version)
190			if circuit == nil {
191				return false, notFoundf("job %q references unknown circuit %q version %d", job.ID, job.Circuit, job.Version)
192			}
193			if !circuit.Frozen {
194				return false, notFrozenf("job %q references circuit %q version %d which is not frozen", job.ID, job.Circuit, job.Version)
195			}
196			if findSetup(s.data.Setups, job.Circuit, job.Version) == nil {
197				return false, setupMissingf("job %q references frozen circuit %q version %d which has no recorded trusted setup",
198					job.ID, job.Circuit, job.Version)
199			}
200			record := persistJob{
201				ID: job.ID, Circuit: job.Circuit, Version: job.Version,
202				Kind: job.Kind, Attempt: job.Attempt, Artifact: job.Artifact,
203			}
204			s.data.Jobs = append(s.data.Jobs, record)
205			result = jobFromPersist(record)
206			return true, nil
207		})
208		return result, err
209	}
210	
211	// GetCircuit returns one circuit version, sorted-field populated exactly as
212	// stored. Unknown versions yield ErrNotFound.
213	func (s *Store) GetCircuit(name string, version int) (Circuit, error) {
214		if err := validateCircuitKey(name, version); err != nil {
215			return Circuit{}, err
216		}
217		var result Circuit
218		err := s.withLockRead(func() error {
219			existing := findCircuit(s.data.Circuits, name, version)
220			if existing == nil {
221				return notFoundf("circuit %q version %d does not exist", name, version)
222			}
223			result = circuitFromPersist(*existing)
224			return nil
225		})
226		return result, err
227	}
228	
229	// ListCircuits returns all stored circuit versions ordered by circuit name
230	// (lexicographically) and then by ascending version number.
231	func (s *Store) ListCircuits() ([]Circuit, error) {
232		var result []Circuit
233		err := s.withLockRead(func() error {
234			ordered := append([]persistCircuit(nil), s.data.Circuits...)
235			sort.Slice(ordered, func(i, j int) bool {
236				if ordered[i].Name != ordered[j].Name {
237					return ordered[i].Name < ordered[j].Name
238				}
239				return ordered[i].Version < ordered[j].Version
240			})
241			result = make([]Circuit, len(ordered))
242			for i, c := range ordered {
243				result[i] = circuitFromPersist(c)
244			}
245			return nil
246		})
247		return result, err
248	}
249	
250	// GetSetup reports whether a trusted setup is registered for the named
251	// frozen version. A missing record yields ErrNotFound.
252	func (s *Store) GetSetup(name string, version int) (Setup, bool, error) {
253		if err := validateCircuitKey(name, version); err != nil {
254			return Setup{}, false, err
255		}
256		var result Setup
257		found := false
258		err := s.withLockRead(func() error {
259			existing := findSetup(s.data.Setups, name, version)
260			if existing == nil {
261				return nil
262			}
263			result = setupFromPersist(*existing)
264			found = true
265			return nil
266		})
267		return result, found, err
268	}
269	
270	// GetJob returns one stored job by id. Unknown ids yield ErrNotFound.
271	func (s *Store) GetJob(id string) (Job, error) {
272		if strings.TrimSpace(id) == "" {
273			return Job{}, invalidf("job id must be non-empty and not only whitespace")
274		}
275		var result Job
276		err := s.withLockRead(func() error {
277			existing := findJob(s.data.Jobs, id)
278			if existing == nil {
279				return notFoundf("job %q does not exist", id)
280			}
281			result = jobFromPersist(*existing)
282			return nil
283		})
284		return result, err
285	}
286	
287	// ListJobs returns all accepted jobs ordered by job id lexicographically.
288	func (s *Store) ListJobs() ([]Job, error) {
289		var result []Job
290		err := s.withLockRead(func() error {
291			ordered := append([]persistJob(nil), s.data.Jobs...)
292			sort.Slice(ordered, func(i, j int) bool { return ordered[i].ID < ordered[j].ID })
293			result = make([]Job, len(ordered))
294			for i, j := range ordered {
295				result[i] = jobFromPersist(j)
296			}
297			return nil
298		})
299		return result, err
300	}
301	
302	// --- validation helpers ---------------------------------------------------
303	
304	func validateCircuitKey(name string, version int) error {
305		if strings.TrimSpace(name) == "" {
306			return invalidf("circuit name must be non-empty and not only whitespace")
307		}
308		if version <= 0 {
309			return invalidf("circuit %q version must be a positive integer, got %d", name, version)
310		}
311		return nil
312	}
313	
314	func validateCounts(constraints, publicInputs, privateInputs int) error {
315		if constraints <= 0 {
316			return invalidf("constraints must be greater than zero, got %d", constraints)
317		}
318		if publicInputs < 0 {
319			return invalidf("public input count must not be negative, got %d", publicInputs)
320		}
321		if privateInputs < 0 {
322			return invalidf("private input count must not be negative, got %d", privateInputs)
323		}
324		return nil
325	}
326	
327	// --- lookup / mapping helpers --------------------------------------------
328	
329	func findCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
330		for i := range cs {
331			if cs[i].Name == name && cs[i].Version == version {
332				return &cs[i]
333			}
334		}
335		return nil
336	}
337	
338	func findSetup(ps []persistSetup, name string, version int) *persistSetup {
339		for i := range ps {
340			if ps[i].Name == name && ps[i].Version == version {
341				return &ps[i]
342			}
343		}
344		return nil
345	}
346	
347	func findJob(js []persistJob, id string) *persistJob {
348		for i := range js {
349			if js[i].ID == id {
350				return &js[i]
351			}
352		}
353		return nil
354	}
355	
356	func sameJobRequest(stored persistJob, request Job) bool {
357		return stored.Circuit == request.Circuit &&
358			stored.Version == request.Version &&
359			stored.Kind == request.Kind &&
360			stored.Attempt == request.Attempt
361	}
362	
363	func circuitFromPersist(c persistCircuit) Circuit {
364		return Circuit{
365			Name: c.Name, Version: c.Version,
366			Constraints: c.Constraints, PublicInputs: c.PublicInputs, PrivateInputs: c.PrivateInputs,
367			Frozen: c.Frozen, Description: c.Description,
368		}
369	}
370	
371	func setupFromPersist(p persistSetup) Setup {
372		return Setup{Name: p.Name, Version: p.Version}
373	}
374	
375	func jobFromPersist(j persistJob) Job {
376		return Job{
377			ID: j.ID, Circuit: j.Circuit, Version: j.Version,
378			Kind: j.Kind, Attempt: j.Attempt, Artifact: j.Artifact,
379		}
380	}
