401			return exitUsage
402		}
403		store, code := openStore(f)
404		if store == nil {
405			return code
406		}
407		defer store.Close()
408	
409		result, err := store.CheckInputFile(f.name, f.version, f.hash, f.file)
410		if err != nil {
411			return reportStoreError(err)
412		}
413		if result.Satisfied {
414			fmt.Printf("input check: satisfied=true name=%s version=%d hash=%s\n",
415				f.name, f.version, result.Hash)
416			return exitOK
417		}
418		fmt.Printf("input check: satisfied=false name=%s version=%d hash=%s first_failure=%d\n",
419			f.name, f.version, result.Hash, result.FirstFailure)
420		return exitOK
421	}
