181			"--constraints", "32", "--description", "d"); code != 0 {
182			t.Fatal("seed create")
183		}
184		if code, _, _ := r("circuit-freeze", "--dir", dir, "--name", "c", "--version", "1"); code != 0 {
185			t.Fatal("seed freeze")
186		}
187		if code, _, _ := r("setup-record", "--dir", dir, "--name", "c", "--version", "1"); code != 0 {
188			t.Fatal("seed setup")
189		}
190		if code, out, _ := r("circuit-get", "--dir", dir, "--name", "c", "--version", "1"); code != 0 && !strings.Contains(out, "frozen=true") {
191			t.Fatalf("state after reopen lost or wrong: code=%d out=%q", code, out)
192		}
193	
194		// Corrupt the committed file: every data command must report a read
195		// failure with exit code 3 and leave the broken file in place.
196		dataFile := filepath.Join(dir, "data.json")
197		original, err := os.ReadFile(dataFile)
198		if err != nil {
199			t.Fatal(err)
200		}
201		bad := append(bytes.Clone(original), []byte("{{not-json")...)
202		if err := os.WriteFile(dataFile, bad, 0o644); err != nil {
203			t.Fatal(err)
204		}
205		code, _, errOut := r("circuit-list", "--dir", dir)
206		if code != 3 || !strings.Contains(errOut, "read failed") {
207			t.Fatalf("corrupt file: code=%d err=%q", code, errOut)
208		}
209		after, err := os.ReadFile(dataFile)
210		if err != nil {
211			t.Fatal(err)
212		}
213		if !bytes.Equal(after, bad) {
214			t.Fatal("corrupt file was modified or overwritten")
215		}
216	}
