413	// Two real processes create disjoint circuit versions; two more then
414	// register setups and submit jobs concurrently. Every acknowledged record
415	// must be present exactly once in the final directory.
416	func TestCrossProcessWriters(t *testing.T) {
417		if os.Getenv("ZKCIRCUIT_HELPER") != "" {
418			t.Skip()
419		}
420		dir := filepath.Join(t.TempDir(), "bench")
421		const per = 25
422	
423		writers := []*helperProc{
424			startHelper(t, dir, "writer", "ZKCIRCUIT_PREFIX=aaa", "ZKCIRCUIT_N="+strconv.Itoa(per)),
425			startHelper(t, dir, "writer", "ZKCIRCUIT_PREFIX=bbb", "ZKCIRCUIT_N="+strconv.Itoa(per)),
426		}
427		var allAcks []ack
428		for _, h := range writers {
429			allAcks = append(allAcks, h.wait(t)...)
430		}
431	
432		jobWriters := []*helperProc{
433			startHelper(t, dir, "setup-job-writer", "ZKCIRCUIT_PREFIX=aaa", "ZKCIRCUIT_N="+strconv.Itoa(per)),
434			startHelper(t, dir, "setup-job-writer", "ZKCIRCUIT_PREFIX=bbb", "ZKCIRCUIT_N="+strconv.Itoa(per)),
435		}
436		for _, h := range jobWriters {
437			allAcks = append(allAcks, h.wait(t)...)
438		}
439	
440		s, err := Open(dir)
441		if err != nil {
442			t.Fatalf("final open: %v", err)
443		}
444		defer s.Close()
445		circuits, err := s.ListCircuits()
446		if err != nil {
447			t.Fatal(err)
448		}
449		if len(circuits) != 2*per {
450			t.Fatalf("want %d circuits, got %d", 2*per, len(circuits))
451		}
452		jobs, err := s.ListJobs()
453		if err != nil {
454			t.Fatal(err)
455		}
456		if len(jobs) != 2*per {
457			t.Fatalf("want %d jobs, got %d", 2*per, len(jobs))
458		}
459		for _, c := range circuits {
460			if !c.Frozen {
461				t.Fatalf("circuit %s v%d not frozen", c.Name, c.Version)
462			}
463		}
464	
465		seen := make(map[string]int)
466		for _, a := range allAcks {
467			seen[a.kind+":"+a.args]++
468		}
469		for token, n := range seen {
470			if n != 1 {
471				t.Fatalf("ack %q observed %d times", token, n)
472			}
473		}
474		for _, a := range allAcks {
475			switch a.kind {
476			case "circuit":
477				parts := strings.Split(a.args, " ")
478				v, _ := strconv.Atoi(parts[1])
479				if _, err := s.GetCircuit(parts[0], v); err != nil {
480					t.Fatalf("acknowledged circuit %s missing: %v", a.args, err)
481				}
482			case "job":
483				if _, err := s.GetJob(a.args); err != nil {
484					t.Fatalf("acknowledged job %s missing: %v", a.args, err)
485				}
486			}
487		}
488	}
489	
490	// Kill writers mid-flight with SIGKILL. Reopening afterwards must show a
491	// complete state, and every record acknowledged before the kill must still
492	// be present and complete.
493	func TestCrossProcessCrashRecovery(t *testing.T) {
494		if os.Getenv("ZKCIRCUIT_HELPER") != "" {
495			t.Skip()
496		}
497		dir := filepath.Join(t.TempDir(), "bench")
498	
499		const victims = 6
500		procs := make([]*helperProc, 0, victims)
501		for i := 0; i < victims; i++ {
502			procs = append(procs, startHelper(t, dir, "crash-writer",
503				"ZKCIRCUIT_PREFIX="+fmt.Sprintf("p%02d", i)))
504		}
505	
506		// Wait until every victim has acknowledged at least one durable commit,
507		// then kill them staggered so some die mid-commit and others between
508		// commits.
509		deadline := time.Now().Add(10 * time.Second)
510		for time.Now().Before(deadline) {
511			ready := 0
512			for _, p := range procs {
513				if p.out.Len() > 0 {
514					ready++
515				}
516			}
517			if ready == victims {
518				break
519			}
520			time.Sleep(time.Millisecond)
521		}
522		for i, p := range procs {
523			if err := p.cmd.Process.Kill(); err != nil {
524				t.Fatal(err)
525			}
526			time.Sleep(2 * time.Millisecond)
527			if i == 1 {
528				// Let the middle victims keep running a few ms longer so kills
529				// land at genuinely different commit points.
530				time.Sleep(15 * time.Millisecond)
531			}
532		}
533	
534		var acks []ack
535		for _, p := range procs {
536			_ = p.cmd.Wait()
537			acks = append(acks, parseAcksLenient(t, p.out.Bytes())...)
538		}
539		if len(acks) == 0 {
540			t.Fatal("no acknowledged commits before kills; test setup is broken")
541		}
542	
543		s, err := Open(dir)
544		if err != nil {
545			t.Fatalf("reopen after SIGKILL storm: %v", err)
546		}
547		defer s.Close()
548		for _, a := range acks {
549			parts := strings.Split(a.args, " ")
550			v, _ := strconv.Atoi(parts[1])
551			c, err := s.GetCircuit(parts[0], v)
552			if err != nil {
553				t.Fatalf("acknowledged record %q lost after crash: %v", a.args, err)
554			}
555			if !c.Frozen || c.Constraints != v || c.Description != parts[0] {
556				t.Fatalf("acknowledged record %q incomplete on disk: %+v", a.args, c)
557			}
558		}
559		list, _ := s.ListCircuits()
560		if len(list) < len(acks) {
561			t.Fatalf("records vanished: %d acknowledged, %d on disk", len(acks), len(list))
562		}
563		t.Logf("crash storm: %d acknowledged records before kill, %d records final", len(acks), len(list))
564	}
