297		if _, err := s.RecordSetup("bare", 1); err != nil {
298			t.Fatal(err)
299		}
300		if _, err := s.SubmitJob(Job{ID: "jb", Circuit: "bare", Version: 1, Kind: "prove", Attempt: 1}); err != nil {
301			t.Fatalf("counts-only job should be accepted: %v", err)
302		}
303		if _, err := s.CompileCircuit("bare", 1); !errors.Is(err, ErrDefinitionMissing) {
304			t.Fatalf("compile without definition: %v", err)
305		}
306	
307		// A real defined version compiles and is idempotent.
308		seedDraftWithDef(t, s, "c", 1, 1, 1, validDef)
309		if _, err := s.FreezeCircuit("c", 1); err != nil {
310			t.Fatal(err)
311		}
312		a1, err := s.CompileCircuit("c", 1)
313		if err != nil {
314			t.Fatalf("compile: %v", err)
315		}
316		if a1.Modulus != 7 || a1.Constraints != 1 || len(a1.Hash) != 64 {
317			t.Fatalf("bad artifact: %+v", a1)
318		}
319		a2, err := s.CompileCircuit("c", 1)
320		if err != nil || a2 != a1 {
321			t.Fatalf("recompile not idempotent: %+v %v", a2, err)
322		}
