324		if err != nil || got != a1 {
325			t.Fatalf("get artifact: %+v %v", got, err)
326		}
327		// A newly added version does not disturb the existing artifact.
328		seedDraftWithDef(t, s, "c", 2, 0, 0,
329			`{"modulus":"13","constraints":[{"a":[],"b":[],"c":[]}]}`)
330		if _, err := s.FreezeCircuit("c", 2); err != nil {
331			t.Fatal(err)
332		}
333		if _, err := s.CompileCircuit("c", 2); err != nil {
334			t.Fatal(err)
335		}
